cat > "$APP/console.css" <<'ALIREZA_D60D84DD9A7F28A7D167D394'
/* Only AI and remote DNS documents load this sheet. Native panel and AdGuard do not. */
body{background:var(--bg);font-size:14px;line-height:1.8}main{max-width:1400px;padding:28px}header{padding:8px 0 22px;border-bottom:1px solid var(--line)}h1{font-size:28px;letter-spacing:-.5px}.card{border-radius:var(--az-r-lg,18px);background:var(--az-card,var(--panel));box-shadow:var(--az-shadow-card,0 12px 36px #0002)}button,.button,input,select,textarea{border-radius:var(--az-r-sm,10px)}button:focus-visible,.button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.chat-layout{gap:16px}.history{position:sticky;top:20px}.history>button{background:var(--az-grad,var(--accent))}.chat{background:linear-gradient(145deg,var(--az-card,var(--panel)),var(--az-surface-1,var(--panel)))}.message{box-shadow:var(--az-shadow-card,0 6px 20px #0001)}.message.user{border-color:color-mix(in srgb,var(--accent) 32%,var(--line));background:color-mix(in srgb,var(--accent) 7%,var(--panel))}.message.model{background:var(--az-surface-2,var(--panel))}.message .copy{opacity:.7}.message:hover .copy,.message:focus-within .copy{opacity:1}.composer{position:relative}.composer textarea{background:var(--az-input-bg,var(--bg));min-height:112px}.suggestions button{border-style:dashed;background:transparent}.eyebrow{font-size:10px;letter-spacing:2px}.steps{counter-reset:step;gap:1px;background:var(--line);border:1px solid var(--line);border-radius:14px;overflow:hidden}.steps span{margin:0;border:0;border-radius:0;background:var(--panel);padding:16px;display:flex;gap:12px;align-items:center}.steps span:before{counter-increment:step;content:counter(step);display:grid;place-items:center;min-width:30px;height:30px;border:1px solid var(--line);border-radius:50%;font-variant-numeric:tabular-nums}.steps span.active{background:color-mix(in srgb,var(--accent) 6%,var(--panel))}.steps span.active:before{background:var(--az-grad,var(--accent));color:var(--az-ac-ink,#fff);border-color:transparent}.node-grid .card{transition:border-color .2s,box-shadow .2s}.node-grid .card:hover{border-color:var(--accent);box-shadow:var(--az-shadow-card-hover,0 12px 30px #0002)}#fingerprint{background:var(--az-input-bg,var(--bg));border-color:var(--accent)}#install>details{padding:16px;border:1px solid var(--line);border-radius:12px}#install summary{cursor:pointer;color:var(--text)}#install>details[open] summary{margin-bottom:14px}#jobs:empty{display:none}.job{background:var(--az-surface-2,var(--panel))}@media(max-width:750px){main{padding:16px 12px}.history{position:static}.chat{padding:14px}.steps span{min-width:100%;padding:12px}.composer .actions{gap:8px}.card{padding:18px}h1{font-size:24px}}
