 async function latest(){const r=await hostAPI();return r.inbounds||[];}
 async function mutate(id,before,edit){if(pending)throw Error(tr('عملیات دیگری در جریان است','Another operation is running'));pending=true;try{const rows=await latest(),inbound=rows.find(i=>i.id===id);if(!inbound)throw Error(tr('اینباند حذف شده است','Inbound no longer exists'));if(JSON.stringify(inbound.profiles||[])!==before)throw Error(tr('میزبان‌ها تغییر کرده‌اند؛ فهرست را تازه کنید','Hosts changed. Refresh the list before editing'));const profiles=edit(structuredClone(inbound.profiles||[]));await hostAPI('PUT',{inboundId:id,expected:before,profiles});}finally{pending=false;}}
 function editor(inbound,index,refresh){const profile=index===null?{}:inbound.profiles[index],before=JSON.stringify(inbound.profiles||[]);const modal=openModal({title:tr('میزبان اشتراک','Subscription host'),body:'<form id="azh-edit" class="azm-grid">'+fields.map(([key,f,e])=>`<div class="field"><label for="azh-${key}">${esc(tr(f,e))}</label><input class="input" id="azh-${key}" name="${key}" dir="${key==='name'?'auto':'ltr'}" type="${key==='port'?'number':'text'}" ${key==='port'?'min="1" max="65535"':''} value="${esc(profile[key])}"></div>`).join('')+advanced(profile)+'<p class="field-err show" role="alert" id="azh-error"></p></form>',okLabel:tr('ذخیره','Save'),onOk:async(close,busy)=>{const f=modal.querySelector('form');if(!f.reportValidity())return;const data={...profile};for(const[key]of fields){const v=f.elements[key].value.trim();if(v)data[key]=key==='port'?Number(v):v;else delete data[key];}if(!data.name&&!data.address){modal.querySelector('#azh-error').textContent=tr('نام یا نشانی را وارد کنید','Enter a name or address');return;}if(data.address&&(/[/@?#\s]/.test(data.address)||data.address.includes('://'))){modal.querySelector('#azh-error').textContent=tr('فقط دامنه یا IP، بدون مسیر و پورت','Use a domain or IP without a path or port');return;}try{readAdvanced(f,data);}catch(e){modal.querySelector('#azh-error').textContent=e.message;return;}busy(true);try{await mutate(inbound.id,before,p=>{if(index===null)p.push(data);else p[index]=data;return p;});close();await refresh();}catch(e){busy(false);modal.querySelector('#azh-error').textContent=e.message;}}});}
 window.alirezaHosts=async()=>{if(typeof isOwner!=='function'||!isOwner())return;const modal=openModal({title:tr('میزبان‌ها','Hosts'),body:`<div class="az-hosts"><div class="az-manual-actions"><input class="input" data-search placeholder="${esc(tr('جست‌وجوی نام، نشانی و اینباند','Search name, address or inbound'))}"><button class="btn primary" data-add-many>${esc(tr('افزودن میزبان','Add hosts'))}</button><button class="btn" data-refresh>${esc(tr('تازه‌سازی','Refresh'))}</button></div><label><input type="checkbox" data-show-hidden> ${esc(tr('نمایش میزبان‌های پنهان','Show hidden hosts'))}</label><div class="az-manual-actions">${[['enable','فعال‌کردن انتخاب‌شده‌ها','Enable selected'],['disable','غیرفعال‌کردن انتخاب‌شده‌ها','Disable selected'],['delete','حذف انتخاب‌شده‌ها','Delete selected']].map(([a,f,e])=>`<button class="btn" data-bulk="${a}" disabled>${esc(tr(f,e))}</button>`).join('')}</div><div data-error class="field-err show" role="alert"></div><div data-hosts></div></div>`,okLabel:tr('بستن','Close'),onOk:close=>close()});const root=modal.querySelector('.az-hosts'),container=root.querySelector('[data-hosts]'),error=root.querySelector('[data-error]');let rows=[];const selected=new Set();const selection=()=>root.querySelectorAll('[data-bulk]').forEach(b=>b.disabled=!selected.size);
 function draw(){container.replaceChildren();const query=root.querySelector('[data-search]').value.trim().toLowerCase();for(const inbound of rows.filter(supported)){const profiles=inbound.profiles||[],filtered=profiles.map((p,index)=>({p,index})).filter(({p})=>(!p.isHidden||root.querySelector('[data-show-hidden]').checked)&&JSON.stringify([p,inbound.remark,inbound.port]).toLowerCase().includes(query));if(query&&!filtered.length)continue;const card=document.createElement('div');card.className='prof-sec';const head=document.createElement('div');head.className='between';const title=document.createElement('strong');title.textContent=(inbound.remark||inbound.protocol)+' · '+inbound.port;const add=document.createElement('button');add.className='btn';add.textContent=tr('＋ افزودن میزبان','＋ Add host');add.onclick=()=>editor(inbound,null,refresh);head.append(title,add);card.append(head);for(const{p,index}of filtered){const row=document.createElement('div');row.className='azh-row';const checkbox=document.createElement('input');checkbox.type='checkbox';const selectionKey=inbound.id+':'+index;checkbox.checked=selected.has(selectionKey);checkbox.setAttribute('aria-label',tr('انتخاب میزبان','Select host'));checkbox.onchange=()=>{if(checkbox.checked)selected.add(selectionKey);else selected.delete(selectionKey);selection();};const name=document.createElement('span');name.textContent=p.name||p.address;const address=document.createElement('code');address.dir='ltr';address.textContent=p.address||tr('نشانی پیش‌فرض','Default address');const actions=document.createElement('div');actions.className='az-manual-actions';for(const[action,f,e]of[['edit','ویرایش','Edit'],['copy','تکثیر','Duplicate'],['remove','حذف','Delete'],['up','↑','↑'],['down','↓','↓'],['toggle',p.isDisabled?'فعال':'غیرفعال',p.isDisabled?'Enable':'Disable']]){const b=document.createElement('button');b.className='btn';b.textContent=tr(f,e);b.disabled=(action==='up'&&index===0)||(action==='down'&&index===profiles.length-1);b.setAttribute('aria-label',action==='up'?tr('انتقال به بالا','Move up'):action==='down'?tr('انتقال به پایین','Move down'):tr(f,e));b.onclick=async()=>{error.textContent='';if(action==='edit'){editor(inbound,index,refresh);return;}if(action==='remove'&&!confirm(tr('این میزبان حذف شود؟ کاربران و اینباند حذف نمی‌شوند.','Delete this host? The inbound and accounts are retained.')))return;b.disabled=true;try{await mutate(inbound.id,JSON.stringify(profiles),list=>{if(action==='remove')list.splice(index,1);else if(action==='toggle')list[index].isDisabled=!p.isDisabled;else if(action==='up'||action==='down'){const next=index+(action==='up'?-1:1);[list[index],list[next]]=[list[next],list[index]];}else list.push({...p,name:(p.name||p.address)+' (copy)'});return list;});await refresh();}catch(e){error.textContent=e.message;}finally{b.disabled=false;}};actions.append(b);}row.append(checkbox,actions,name,address);card.append(row);}if(!profiles.length){const note=document.createElement('p');note.className='az-manual-note';note.textContent=tr('این اینباند با نشانی پیش‌فرض در اشتراک ارائه می‌شود.','This inbound uses its default subscription address.');card.append(note);}container.append(card);}if(!container.children.length){const p=document.createElement('p');p.textContent=tr('اینباند سازگاری پیدا نشد.','No matching compatible inbound.');container.append(p);}}
 async function refresh(){selected.clear();selection();error.textContent='';const b=root.querySelector('[data-refresh]');b.disabled=true;try{rows=await latest();draw();}catch(e){error.textContent=e.message;}finally{b.disabled=false;}}
 for(const b of root.querySelectorAll('[data-bulk]'))b.onclick=async()=>{if(pending||!selected.size)return;const action=b.dataset.bulk;if(!confirm(tr('عملیات روی تمام میزبان‌های انتخاب‌شده انجام شود؟','Apply to every selected host?')))return;pending=true;error.textContent='';try{const updates=[];for(const inbound of rows){const chosen=new Set((inbound.profiles||[]).map((p,i)=>selected.has(inbound.id+':'+i)?i:-1).filter(i=>i>=0));if(!chosen.size)continue;const profiles=(inbound.profiles||[]).flatMap((p,i)=>!chosen.has(i)?[p]:action==='delete'?[]:[{...p,isDisabled:action==='disable'}]);updates.push({inboundId:inbound.id,expected:JSON.stringify(inbound.profiles||[]),profiles});}await hostAPI('PUT',{updates});await refresh();}catch(e){error.textContent=e.message;}finally{pending=false;}};
 root.querySelector('[data-add-many]').onclick=()=>{const eligible=rows.filter(supported);if(!eligible.length){error.textContent=tr('ابتدا یک اینباند سازگار بسازید','Create a compatible inbound first');return;}const modal=openModal({title:tr('افزودن میزبان به چند اینباند','Add hosts to multiple inbounds'),body:'<form data-many><div class="field"><label>'+esc(tr('یک دامنه یا IP در هر سطر','One domain or IP per line'))+'</label><textarea class="input" dir="ltr" name="addresses" rows="5" required></textarea></div><div class="field"><label>'+esc(tr('نام نمایشی؛ برای چند آدرس شماره افزوده می‌شود','Display name; multiple addresses are numbered'))+'</label><input class="input" name="displayName"></div><div class="prof-sec">'+eligible.map(i=>'<label class="inb-multi-row"><input type="checkbox" name="inbound" value="'+esc(i.id)+'"> '+esc((i.remark||i.protocol)+' · '+i.port)+'</label>').join('')+'</div><div class="field-err show" data-many-error></div></form>',okLabel:tr('افزودن','Add'),onOk:async(close,lock)=>{const f=modal.querySelector('form'),err=modal.querySelector('[data-many-error]');if(pending)return;try{const addresses=[...new Set(f.elements.addresses.value.split(/\s+/).map(v=>v.trim()).filter(Boolean))],chosen=new Set([...f.querySelectorAll('[name=inbound]:checked')].map(x=>x.value));if(!addresses.length||!chosen.size)throw Error(tr('نشانی و حداقل یک اینباند انتخاب کنید','Enter addresses and select at least one inbound'));if(addresses.some(v=>/[/@?#\s]/.test(v)||v.includes('://')))throw Error(tr('فقط دامنه یا IP بدون مسیر وارد کنید','Enter domains or IPs without paths'));const name=f.elements.displayName.value.trim(),updates=eligible.filter(i=>chosen.has(i.id)).map(i=>{const old=i.profiles||[];if(old.length+addresses.length>64)throw Error(tr('حداکثر 64 میزبان برای هر اینباند','Maximum 64 hosts per inbound'));return{inboundId:i.id,expected:JSON.stringify(old),profiles:[...old,...addresses.map((address,n)=>({address,name:name?(addresses.length>1?name+' '+(n+1):name):address}))]};});lock(true);pending=true;await hostAPI('PUT',{updates});close();await refresh();}catch(e){err.textContent=e.message;lock(false);}finally{pending=false;}}});};
 root.querySelector('[data-refresh]').onclick=refresh;root.querySelector('[data-search]').oninput=draw;root.querySelector('[data-show-hidden]').onchange=draw;await refresh();};
 const style=document.createElement('style');style.textContent='#azh-edit>details{grid-column:1/-1}#azh-edit details>.field{margin-block:12px}.az-hosts .prof-sec{padding:16px 0;border-bottom:1px solid var(--bd)}.az-hosts [data-search]{flex:1;min-width:160px}.azh-row{display:flex;flex-wrap:wrap;gap:12px;align-items:center;padding:12px 0}.azh-row>span{flex:1;min-width:100px}.azh-row code{overflow-wrap:anywhere}.az-hosts .between{display:flex;align-items:center;justify-content:space-between;gap:12px}';document.head.append(style);
})();
