cat > "$APP/bot-bridge.mjs" <<'ALIREZA_05DB0B57BCD04203B2294F45'
// SPDX-License-Identifier: GPL-3.0-or-later
// Narrow 3x-ui compatibility surface for Mirza. Existing Nova accounts are never adopted.
import {randomBytes,randomUUID} from 'node:crypto';
import {readFileSync,writeFileSync,mkdirSync,renameSync} from 'node:fs';
const root=process.env.ALIREZA_ROOT||'/var/lib/alirezaserver';
const fail=(message,status=400)=>Object.assign(Error(message),{status});
export function createBridge(native,{load,save}={}){
 load ||=()=>{try{return JSON.parse(readFileSync(root+'/bot-users.json'));}catch(e){if(e.code==='ENOENT')return {};throw e;}};
 save ||=v=>{mkdirSync(root,{recursive:true,mode:0o700});writeFileSync(root+'/bot-users.json.tmp',JSON.stringify(v),{mode:0o600});renameSync(root+'/bot-users.json.tmp',root+'/bot-users.json');};
 let queue=Promise.resolve();
 const serial=f=>{const p=queue.then(f);queue=p.catch(()=>{});return p;};
 const answer=obj=>({success:true,msg:'',obj});
 async function users(){return(await native('/admin/network-settings.json')).users||[];}
 async function lookup(name){const all=load(),entry=all[name]||Object.values(all).find(v=>v.uuid===name),u=entry&&(await users()).find(u=>u.id===entry.id);if(!entry||!u)throw fail('BOT_ACCOUNT_NOT_FOUND',404);return{entry,u,all};}
 const expiry=u=>u.expiry?Date.parse(u.expiry):0;
 const client=(u,entry)=>({id:u.uuid,email:entry.name,enable:u.enabled!==false,totalGB:Number(u.quotaBytes)||0,expiryTime:expiry(u),limitIp:Number(u.ipLimit)||0,subId:entry.subId,comment:u.note||''});
