 run(['bash','-n',str(script)])
 lock=json.loads((HERE/'tunnel-downloads.json').read_text());arch=os.uname().machine;arch={'x86_64':'amd64','aarch64':'arm64'}.get(arch)
 if not arch:raise RuntimeError('UNSUPPORTED_ARCHITECTURE')
 for entry in lock[arch]:
  if all((APP/'bin'/b).exists() and hashlib.sha256((APP/'bin'/b).read_bytes()).hexdigest()==entry['binarySHA256'][b] for b in entry['binaries']):continue
