  if hashlib.sha256(packed).hexdigest()!=corelock[arch]['compressedSHA256']:raise RuntimeError('CARRIER_PAYLOAD_CHECKSUM')
  with gzip.GzipFile(fileobj=io.BytesIO(packed)) as stream:core=stream.read(corelock[arch]['bytes']+1)
  if len(core)!=corelock[arch]['bytes'] or hashlib.sha256(core).hexdigest()!=corelock[arch]['sha256']:raise RuntimeError('CARRIER_CORE_CHECKSUM')
  (APP/'bin/gre-panel').write_bytes(core);(APP/'bin/gre-panel').chmod(0o700)
