 for name in ['hashem-manager.py','hashem-source.sh','reference-versions.json','tunnel-downloads.json','hashem-core-build.json','COPYING.Hashem']:
  source=HERE/name;target=adapter/name
  if source.resolve()!=target.resolve():shutil.copyfile(source,target);target.chmod(0o600)
