def read_json(p):
 try:return json.loads(p.read_text())
 except FileNotFoundError:return {}
def interface_status():
 try:
  result=subprocess.run(['ip','-j','-s','link','show','dev','az-hashem-gre'],capture_output=True,text=True,timeout=5)
  data=json.loads(result.stdout or '[]')
  if not data:return None
  value=data[0];stats=value.get('stats64',value.get('stats',{}));return {'name':'az-hashem-gre','up':'UP' in value.get('flags',[]),'mtu':value.get('mtu'),'rx':stats.get('rx',{}),'tx':stats.get('tx',{})}
 except (OSError,ValueError,subprocess.TimeoutExpired):return None
def status():
 services={};pids={}
 owned=[name for name in UNITS if (SYSTEMD/(name+'.service')).exists() and (SYSTEMD/(name+'.service')).read_text().startswith(MARKER)]
 if owned:
  result=subprocess.run(['systemctl','show','--no-pager','--property=Id,ActiveState,MainPID',*owned],capture_output=True,text=True,timeout=10)
  for block in result.stdout.split('\n\n'):
   values=dict(line.split('=',1) for line in block.splitlines() if '=' in line);name=values.get('Id','').removesuffix('.service')
   if name in owned:services[name]=values.get('ActiveState','unknown');pids[name]=int(values.get('MainPID','0'))
  for name in owned:services.setdefault(name,'unknown')
 carrier=read_json(CFG/'state/carrier.json');watchdog=read_json(CFG/'state/watchdog.json');wssfile=CFG/'state/wss-status.json';wss=read_json(wssfile)
 if wss:
  wss['stale']=not wssfile.exists() or time.time()-wssfile.stat().st_mtime>10 or services.get('alireza-hashem-carrier')!='active'
  if wss['stale']:wss['running']=False;wss['connected']=False
 return {'installed':(APP/'bin/hashem.sh').exists(),'services':services,'servicePids':pids,'interface':interface_status() if any('gre' in name for name in owned) else {},'carrier':{k:carrier[k] for k in ['mode','active_carrier','switch_count','last_switch'] if k in carrier},'watchdog':{k:watchdog[k] for k in ['enabled','interval_sec','consec_fails','last_check'] if k in watchdog},'wss':wss,'performance':read_json(CFG/'state/perf.json'),'pool':read_json(CFG/'state/auto_pool.json'),'benchmark':read_json(ROOT/'benchmark.json'),'configuration':{k:v for k,v in read_json(ROOT/'last-config.json').items() if k!='token'},'snapshots':sorted(p.name for p in (ROOT/'snapshots').glob('*') if p.is_dir())[-10:]}
def firewall_rules():
 rules={}
 for table in ['filter','nat','mangle']:
  try:text=run(['iptables-save','-t',table],10)
  except (RuntimeError,FileNotFoundError):continue
  entries=[];positions={}
  for line in text.splitlines():
   if not line.startswith('-A '):continue
   chain=shlex.split(line)[1];positions[chain]=positions.get(chain,0)+1
   if '--comment alirezaserver-hashem' in line.replace('"',''):entries.append({'rule':line,'position':positions[chain]})
  rules[table]=entries
 return rules
def restore_firewall(saved):
 current=firewall_rules()
 for table in sorted(set(current)|set(saved)):
  for line in current.get(table,[]):
   args=shlex.split(line['rule'] if isinstance(line,dict) else line);args[0]='-D';subprocess.run(['iptables','-t',table,*args],capture_output=True,timeout=10)
  for line in saved.get(table,[]):
   args=shlex.split(line['rule'] if isinstance(line,dict) else line)
   if isinstance(line,dict):args[0]='-I';args.insert(2,str(line['position']))
   run(['iptables','-t',table,*args],10)
def snapshot():
 dest=ROOT/'snapshots'/str(time.time_ns());dest.mkdir(parents=True,mode=0o700)
 if CFG.exists():shutil.copytree(CFG,dest/'config')
 for name in UNIT_FILES:
  p=SYSTEMD/name
  if p.exists() and p.read_text().startswith(MARKER):shutil.copy2(p,dest/p.name)
 (dest/'timer-active.json').write_text(json.dumps({n:subprocess.run(['systemctl','is-active',n],capture_output=True,text=True,timeout=5).stdout.strip() for n in UNIT_FILES if n.endswith('.timer') and (SYSTEMD/n).exists()}))
 if (ROOT/'last-config.json').exists():shutil.copy2(ROOT/'last-config.json',dest/'last-config.json')
 (dest/'enabled.json').write_text(json.dumps({n:subprocess.run(['systemctl','is-enabled',n],capture_output=True,text=True,timeout=5).stdout.strip() for n in UNIT_FILES if (SYSTEMD/n).exists()}))
 (dest/'firewall.json').write_text(json.dumps(firewall_rules()))
 (dest/'active.json').write_text(json.dumps(status()['services']))
 for old in sorted(p for p in (ROOT/'snapshots').iterdir() if p.is_dir() and not p.is_symlink() and re.fullmatch(r'\d{10,30}',p.name))[:-10]:shutil.rmtree(old)
 return dest
def cleanup_fou(keep=None):
 keep=keep or set()
 for p in (CFG/'state').glob('.owned-fou-*'):
  number=p.name.removeprefix('.owned-fou-')
  if number.isdigit() and p.name not in keep:
   subprocess.run(['ip','fou','del','port',number],capture_output=True,timeout=10);p.unlink()
def restore(dest):
 cleanup_fou({p.name for p in (dest/'config/state').glob('.owned-fou-*')})
 newgre=(SYSTEMD/'alireza-hashem-az-hashem-gre.service').exists() and not(dest/'alireza-hashem-az-hashem-gre.service').exists()
 for name in UNIT_FILES:
  p=SYSTEMD/name;backup=dest/p.name
  if p.exists() and p.read_text().startswith(MARKER):subprocess.run(['systemctl','disable','--now',name],capture_output=True,timeout=30);p.unlink()
  if backup.exists():shutil.copy2(backup,p)
 if newgre:subprocess.run(['ip','link','delete','az-hashem-gre'],capture_output=True,timeout=10)
 restore_firewall(read_json(dest/'firewall.json'))
 if (dest/'config').exists():
  if CFG.exists():shutil.rmtree(CFG)
  shutil.copytree(dest/'config',CFG)
 if (dest/'last-config.json').exists():shutil.copy2(dest/'last-config.json',ROOT/'last-config.json')
 else:(ROOT/'last-config.json').unlink(missing_ok=True)
 run(['systemctl','daemon-reload'])
 for name,state in read_json(dest/'enabled.json').items():
  if state=='enabled':run(['systemctl','enable',name],15)
 for name,state in {**read_json(dest/'active.json'),**read_json(dest/'timer-active.json')}.items():
  if state=='active':run(['systemctl','start',name],30)
def apply_carrier(c):
 if c['engine']=='backhaul':return
 state=CFG/'state';state.mkdir(parents=True,exist_ok=True,mode=0o700)
 (state/'setup.json').write_text(json.dumps(c));(state/'setup.json').chmod(0o600)
 mode=c['carrier'];carrier=read_json(state/'carrier.json');carrier.update(mode=mode,candidates=['direct','fou:443','fou:55555','wss:8443'])
 (state/'carrier.json').write_text(json.dumps(carrier));(state/'carrier.json').chmod(0o600)
 if mode.startswith('wss:') or mode=='auto':
  port=int(mode.split(':')[1]) if ':' in mode else 8443
  wss={'enabled':True,'role':'server' if c['role']=='iran' else 'client','listen_port':port,'remote_addr':c['remotePub']+':'+str(port),'local_bridge_udp':29998,'auth_token':c['token'],'use_tls':True,'sni':c['remotePub'],'insecure_tls':c['wssInsecure']}
  (state/'wss_carrier.json').write_text(json.dumps(wss));(state/'wss_carrier.json').chmod(0o600)
  unit=MARKER+'[Unit]\nDescription=alirezaserver Hashem WSS carrier\nAfter=network-online.target\n[Service]\nExecStart='+str(APP/'bin/gre-panel')+' carrier\nEnvironment=GRE_PANEL_DIR='+str(state)+'\nRestart=on-failure\nRestartSec=3\nLogRateLimitIntervalSec=30s\nLogRateLimitBurst=200\nNoNewPrivileges=true\nPrivateTmp=true\nProtectSystem=strict\nReadWritePaths='+str(state)+'\n[Install]\nWantedBy=multi-user.target\n'
  (SYSTEMD/'alireza-hashem-carrier.service').write_text(unit);run(['systemctl','daemon-reload']);run(['systemctl','enable','--now','alireza-hashem-carrier'],20)
  run(['systemctl','restart','alireza-hashem-carrier'],20)
 else:
  unit=(SYSTEMD/'alireza-hashem-carrier.service')
