def check_ports(c,carrier_only=False):
 # Never reuse a port held by Nova, DNS, SSH or another service.
 ports=run(['ss','-H','-lntup'])
 owned=['pid='+str(pid)+',' for pid in status().get('servicePids',{}).values() if pid>0]
 check=[] if carrier_only or c['role']=='foreign' else [c['port'],c['port']+1]+c['ports']
 if not carrier_only and c['role']=='iran' and c['transport']=='wss':check.append(c['port']+2 if c['port']+2<=65535 else c['port']-2)
 if c['carrier']=='auto':check += [443,55555,29998,29999]+([8443] if c['role']=='iran' else [])
 elif c['carrier'].startswith('fou:'):check += [int(c['carrier'].split(':')[1])]
 elif c['carrier'].startswith('wss:'):check += [29998,29999]+([int(c['carrier'].split(':')[1])] if c['role']=='iran' else [])
 for port in check:
  for line in ports.splitlines():
   if re.search(r':'+str(port)+r'\s',line) and not any(pid in line for pid in owned):raise RuntimeError('PORT_IN_USE:'+str(port))

def network_guard(c):
 if c['engine']=='backhaul':return
