 numbers=[443,55555,29998] if c['carrier']=='auto' else [int(c['carrier'].split(':')[1])] if c['carrier'].startswith('fou:') else [29998] if c['carrier'].startswith('wss:') else []
 for number in numbers:
  if re.search(r'(?m)^port '+str(number)+r'\s',fou) and not(CFG/'state'/('.owned-fou-'+str(number))).exists():raise RuntimeError('FOU_PORT_CONFLICT:'+str(number))
