  proc=subprocess.Popen(['bash',str(APP/'bin/hashem.sh'),*args],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True,env={**os.environ,'ALIREZA_HASHEM_TOKEN':c['token'],'GRE_SKIP_PANEL':'1','GRE_PANEL_DIR':str(CFG/'state'),'PATH':str(APP/'bin')+':'+os.environ.get('PATH','')})
