   except subprocess.TimeoutExpired:os.killpg(proc.pid,signal.SIGKILL);proc.communicate()
   raise
  finally:
   for name in UNITS:
    p=(SYSTEMD/(name+'.service'))
    if p.exists() and (not before[name] or p.read_text().startswith(MARKER)):
     text=p.read_text()
     if not text.startswith(MARKER):p.write_text(MARKER+text)
   timer=(SYSTEMD/'alireza-hashem-hashem-watchdog.timer')
   if timer.exists() and not timer.read_text().startswith(MARKER):timer.write_text(MARKER+timer.read_text())
  for name in UNITS:
   p=(SYSTEMD/(name+'.service'))
   if p.exists() and (not before[name] or p.read_text().startswith(MARKER)):
    text=p.read_text()
    if not text.startswith(MARKER):p.write_text(MARKER+text)
