  for kind in ['tcp','udp']:
   b=templates[kind];b=re.sub(r'(?m)^name\s*=.*$', 'name = "'+kind+'_'+str(port)+'"',b);b=re.sub(r'(?m)^(localPort|remotePort)\s*=.*$',lambda m:m[1]+' = '+str(port),b);generated.append(b)
 return prefix+''.join('[[proxies]]\n'+b for b in kept+generated)
