  temp.replace(path);state=CFG/'state';state.mkdir(parents=True,exist_ok=True,mode=0o700);(state/'perf.json').write_text(json.dumps({**value,'frp_pool_count':pool,'frp_max_pool':maximum}));(state/'perf.json').chmod(0o600)
