                echo -e "${CYAN}=== Add Foreign Server to Cluster ===${NC}"
                read -p "Foreign Server Name (e.g. kharej-de-1): " FN_NAME
                [[ -z "$FN_NAME" ]] && { echo -e "${RED}[!] Name cannot be empty.${NC}"; pause_prompt; continue; }
