cli_setup_gre_backhaul_foreign() {
    local LOCAL_PUB="" REMOTE_PUB="" PORT="" LOCAL_GRE="" PEER_GRE="" TRANSPORT="tcpmux" TOKEN="" BUNDLE="" FORCE=0
    local FOREIGN_GRE_DEF="$FOREIGN_GRE_IP" IRAN_GRE_DEF="$IRAN_GRE_IP"
