cat > "$APP/hashem-ui.js" <<'ALIREZA_B7BF3BF8FAB6A2705A86D7FA'
/* SPDX-License-Identifier: GPL-3.0-or-later */
(()=>{'use strict';if(typeof viewTunnel!=='function'||typeof openModal!=='function')return;
 const base=(window.__NOVA_BASE__||'')+'/alireza/',fa=()=>document.documentElement.lang==='fa'||document.documentElement.dir==='rtl',tr=(f,e)=>fa()?f:e,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 async function api(path,method='GET',data){const r=await fetch(base+'api/hashem/'+path,{method,credentials:'same-origin',cache:'no-store',headers:data?{'content-type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok)throw Error(j.error||'HASHEM_FAILED');return j;}
 const field=(k,label,value='',type='text')=>`<div class="field"><label for="azh-${k}">${esc(label)}</label><input class="input" name="${k}" id="azh-${k}" type="${type}" value="${esc(value)}" dir="ltr" autocomplete="off"></div>`;
