 function attach(section){if(typeof isOwner!=='function'||!isOwner()||section.querySelector('[data-hashem]'))return section;const card=document.createElement('section');card.className='card az-hashem';card.dataset.hashem='';card.innerHTML=`<div class="view-head"><div class="htxt"><h2>NOVA Tunnel · Hashem</h2><a target="_blank" rel="noopener" href="${esc(base+'hashem/source.tar.gz')}">Source · AGPL-3.0</a><p>${esc(tr('GRE، FRP، Backhaul، انتقال WSS و بازیابی مستقل؛ تونل‌های قبلی نوا حفظ می‌شوند.','GRE, FRP, Backhaul, WSS transport and independent recovery. Existing Nova tunnels are retained.'))}</p></div><div class="az-manual-actions">${[['refresh','تازه‌سازی','Refresh'],['install','نصب هسته‌ها','Install cores'],['setup','راه‌اندازی تانل','Set up tunnel'],['restart','راه‌اندازی مجدد','Restart'],['remove','توقف و حذف سرویس','Stop / remove services']].map(([a,f,e])=>`<button class="btn ${a==='setup'?'primary':''}" data-hashem-action="${a}">${esc(tr(f,e))}</button>`).join('')}</div></div><div data-hashem-status></div><div class="az-manual-actions">${[['performance','تنظیمات عملکرد FRP','FRP performance'],['ports','ویرایش پورت‌ها','Edit ports'],['sync','پورت‌های اینباندها','Inbound ports'],['inbounds','ساخت اینباندهای متناظر','Create matching inbounds'],['carrier','تغییر Carrier','Change carrier'],['watchdog','Watchdog','Watchdog'],['benchmark','آزمون اتصال','Connection benchmark'],['backup','نقطهٔ بازگشت','Restore point'],['restore','بازگشت','Restore'],['logs','لاگ‌ها','Logs']].map(([a,f,e])=>`<button class="btn" data-hashem-action="${a}">${esc(tr(f,e))}</button>`).join('')}</div><div data-hashem-jobs role="status"></div><div class="field-err show" data-hashem-error role="alert"></div>`;section.append(card);const error=card.querySelector('[data-hashem-error]');let state={},timer=null,busy=false;
