y({operation:'ports',ports:parsePorts().join(',')})),output=modal.querySelector('[data-peer-output]');output.hidden=false;output.value="printf '%s' '"+payload+"' | base64 -d | sudo python3 /opt/alirezaserver-hashem/adapter/hashem-manager.py";modal.querySelector('[data-peer-copy]').hidden=false;}catch(e){modal.querySelector('[data-port-error]').textContent=e.message;}};modal.querySelector('[data-peer-copy]').onclick=()=>navigator.clipboard.writeText(modal.querySelector('[data-peer-output]').value).catch(()=>modal.querySelector('[data-peer-output]').select());return;}if(a==='carrier'){if(state.configuration?.engine==='backhaul'){error.textContent=tr('Backhaul مستقیم از Carrier مربوط به GRE استفاده نمی‌کند.','Direct Backhaul does not use a GRE carrier.');return;}const modal=openModal({title:tr('انتقال GRE','GRE carrier'),body:'<form>'+select('carrier','Carrier',['direct','fou:443','fou:55555','wss:8443','auto'])+'<p class="az-manual-note">'+esc(tr('تنظیمات متناظر باید در دو سمت هماهنگ باشند. پورت و سرویس‌های دیگر بررسی می‌شوند.','Both endpoints must use matching settings. Conflicting ports and services are checked.'))+'</p></form>',okLabel:tr('اعمال','Apply'),onOk:async close=>{const mode=modal.querySelector('select').value;close();await action('carrier',{mode});}});modal.querySelector('select').value=state.carrier?.mode||'direct';return;}if(a==='watchdog'){await action('watchdog',{enabled:!state.watchdog?.enabled});return;}if(a==='restore'){const snapshots=state.snapshots||[];if(!snapshots.length){error.textContent=tr('هنوز نقطهٔ بازگشتی وجود ندارد.','No restore points exist yet.');return;}const modal=openModal({title:tr('بازگردانی تانل','Restore tunnel'),body:select('snapshot',tr('نقطهٔ بازگشت','Restore point'),snapshots.slice().reverse()),okLabel:tr('بازگردانی','Restore'),onOk:async close=>{const snapshot=modal.querySelector('select').value;close();await action('restore',{snapshot});}});return;}await action(a);});refresh();return section;}
